vertex:
#version 300 es

layout(std140) uniform ObjectUniformBuffer
{
    mat4 g_mModel;
    mat4 g_mView;
    mat4 g_mProj;
    vec3 g_vLightPos;
    vec3 g_vLightColor;
    vec3 g_vCameraPos;
    float g_flTime;
} g_oUbo;

layout(location = 0) in vec3 position;
out vec2 vdspv_fsin0_vTexCoords;
out vec3 vdspv_fsin0_vViewPosition;
layout(location = 2) in vec2 texCoords;
flat out int vdspv_fsin5;
layout(location = 3) in int texIndex;
layout(location = 1) in vec3 normal;
layout(location = 4) in uint matFlags;

void main()
{
    vec4 pos = g_oUbo.g_mModel * vec4(position, 1.0);
    vdspv_fsin0_vTexCoords = texCoords;
    vdspv_fsin0_vViewPosition = vec3((g_oUbo.g_mView * pos).xyz);
    gl_Position = (g_oUbo.g_mProj * g_oUbo.g_mView) * pos;
    vdspv_fsin5 = texIndex;
    gl_Position.z = 2.0 * gl_Position.z - gl_Position.w;
    gl_Position.y = -gl_Position.y;
}

fragment:
#version 300 es
precision mediump float;
precision highp int;

uniform highp sampler2D Color0;
uniform highp sampler2D Color1;
uniform highp sampler2D Color2;
uniform highp sampler2D Color3;
uniform highp sampler2D Color4;
uniform highp sampler2D Color5;
uniform highp sampler2D Color6;
uniform highp sampler2D Color7;

in highp vec2 vdspv_fsin0_vTexCoords;
in highp vec3 vdspv_fsin0_vViewPosition;
flat in int vdspv_fsin5;
layout(location = 0) out highp vec4 fragColor;

void main()
{
    highp vec2 uv = vdspv_fsin0_vTexCoords;
    highp vec4 color = vec4(1.0, 0.0, 1.0, 1.0);
    if (vdspv_fsin5 == 0)
    {
        color = texture(Color0, uv);
    }
    if (vdspv_fsin5 == 1)
    {
        color = texture(Color1, uv);
    }
    if (vdspv_fsin5 == 2)
    {
        color = texture(Color2, uv);
    }
    if (vdspv_fsin5 == 3)
    {
        color = texture(Color3, uv);
    }
    if (vdspv_fsin5 == 4)
    {
        color = texture(Color4, uv);
    }
    if (vdspv_fsin5 == 5)
    {
        color = texture(Color5, uv);
    }
    if (vdspv_fsin5 == 6)
    {
        color = texture(Color6, uv);
    }
    if (vdspv_fsin5 == 7)
    {
        color = texture(Color7, uv);
    }
    if (color.w < 0.5)
    {
        discard;
    }
    highp float viewSpaceDepth = length(vdspv_fsin0_vViewPosition);
    highp float fogFactor = clamp(exp(viewSpaceDepth * 0.00999999977648258209228515625) * 0.02500000037252902984619140625, 0.0, 1.0);
    fragColor = vec4(mix(color.xyz, vec3(0.30099999904632568359375, 0.839999973773956298828125, 1.0), vec3(fogFactor)), 1.0);
}
